                return new PortalInfo(target, velocity, yRot, xRot);
            }

            public Entity placeEntity(Entity source, ServerLevel currentLevel, ServerLevel targetLevel, float ignoredYaw, Function<Boolean, Entity> repositionEntity) {
                Entity moved = repositionEntity.apply(false);
                if (moved != null) {
